/**
 * NetworkNodeManager.js — the four network node types in 3D.
 *
 * Each node is loaded from public/models/*.glb (generated by
 * blender/generate_all_models.py). If a GLB is missing or fails to parse, an
 * equivalent procedural model built from Three.js primitives is used instead,
 * so the twin always runs — with or without the Blender assets.
 *
 * Every model exposes a `BeamAnchor` node where energy beams attach.
 */
import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { mergeGeometries } from 'three/addons/utils/BufferGeometryUtils.js';
import { CSS2DObject } from 'three/addons/renderers/CSS2DRenderer.js';
import { INTERFACE_SPECS } from '../simulation/LinkModel.js';

const loader = new GLTFLoader();
const MODEL_BASE = `${import.meta.env?.BASE_URL ?? './'}models/`;
const OUTAGE_TINT = new THREE.Color('#ff2d55');

/** Load a GLB if it exists; resolves to null (never throws) so callers can fall back. */
export async function loadGLB(file) {
  const url = `${MODEL_BASE}${file}`;
  try {
    const head = await fetch(url, { method: 'HEAD', cache: 'no-cache' });
    const type = head.headers.get('content-type') || '';
    if (!head.ok || type.includes('text/html')) return null;
    const gltf = await loader.loadAsync(url);
    return gltf.scene;
  } catch (err) {
    console.info(`[FlexiPath] ${file} unavailable (${err?.message ?? err}) — using procedural fallback`);
    return null;
  }
}

/**
 * Collect the intentionally glowing materials of a model (and boost them for bloom).
 * Faint emission (e.g. foil sheen, PV tint) is left alone so it doesn't bloom like a lamp.
 */
export function collectEmissives(root, boost = 2.2, minGlow = 0.9) {
  const list = [];
  const seen = new Set();
  root.traverse((o) => {
    if (!o.isMesh) return;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    for (const m of mats) {
      if (!m.emissive || seen.has(m)) continue;
      const e = m.emissive;
      const glow = Math.max(e.r, e.g, e.b) * (m.emissiveIntensity ?? 1);
      if (glow < minGlow) continue;
      seen.add(m);
      m.emissiveIntensity = Math.max(m.emissiveIntensity ?? 1, boost);
      m.userData.baseEmissive = m.emissiveIntensity;
      m.userData.baseEmissiveColor = e.clone();
      list.push(m);
    }
  });
  return list;
}

// ── Procedural material kit ────────────────────────────────────────────────
const M = {
  metal: (color = '#1e293b', rough = 0.35) => new THREE.MeshStandardMaterial({ color, metalness: 0.85, roughness: rough }),
  matte: (color = '#0f172a') => new THREE.MeshStandardMaterial({ color, metalness: 0.2, roughness: 0.8 }),
  glow: (color, intensity = 2.6) =>
    new THREE.MeshStandardMaterial({ color: '#05080f', emissive: new THREE.Color(color), emissiveIntensity: intensity, roughness: 0.4 }),
  gold: () => new THREE.MeshStandardMaterial({ color: '#d9a21b', metalness: 1, roughness: 0.28, emissive: new THREE.Color('#3a2400'), emissiveIntensity: 0.4 }),
  pv: () => new THREE.MeshStandardMaterial({ color: '#0b1d4d', metalness: 0.6, roughness: 0.22, emissive: new THREE.Color('#0a1f5c'), emissiveIntensity: 0.6 }),
};

function mesh(geo, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(geo, mat);
  m.position.set(x, y, z);
  return m;
}

function anchor(root, x, y, z) {
  const a = new THREE.Object3D();
  a.name = 'BeamAnchor';
  a.position.set(x, y, z);
  root.add(a);
  return a;
}

/** Cylinder between two points (for lattice members). */
function strut(a, b, r) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const geo = new THREE.CylinderGeometry(r, r, len, 5, 1, true);
  geo.translate(0, len / 2, 0);
  const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  geo.applyQuaternion(q);
  geo.translate(a.x, a.y, a.z);
  return geo;
}

export function buildWiredNode() {
  const root = new THREE.Group();
  const blue = INTERFACE_SPECS.eth0.color;
  root.add(mesh(new THREE.CylinderGeometry(1.25, 1.45, 0.3, 32), M.metal('#111827'), 0, 0.15, 0));
  root.add(mesh(new THREE.CylinderGeometry(1.3, 1.3, 0.04, 32), M.glow(blue, 1.8), 0, 0.32, 0));
  root.add(mesh(new RoundedBoxGeometry(0.75, 1.7, 0.6, 3, 0.08), M.metal('#0b1220', 0.3), 0, 1.15, 0));
  root.add(mesh(new THREE.BoxGeometry(0.06, 1.3, 0.2), M.glow(blue, 3), 0.39, 1.1, 0));
  root.add(mesh(new RoundedBoxGeometry(1.05, 0.62, 0.8, 3, 0.1), M.metal('#1e293b', 0.25), 0.05, 2.1, 0));
  const ring = mesh(new THREE.TorusGeometry(0.42, 0.06, 14, 48), M.glow(blue, 3.4), 0.6, 2.1, 0);
  ring.rotation.y = Math.PI / 2;
  root.add(ring);
  root.add(mesh(new THREE.CylinderGeometry(0.16, 0.16, 0.12, 20), M.glow('#93c5fd', 2.4), 0.6, 2.1, 0).rotateZ(Math.PI / 2));
  // Charging cables curving down to both parking bays.
  const cableMat = M.matte('#0f172a');
  for (const side of [-1, 1]) {
    const curve = new THREE.CatmullRomCurve3([
      new THREE.Vector3(0.3, 1.8, side * 0.25),
      new THREE.Vector3(1.6, 0.35, side * 1.6),
      new THREE.Vector3(2.9, 0.2, side * 2.6),
    ]);
    root.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 24, 0.06, 6), cableMat));
  }
  anchor(root, 0.6, 2.1, 0);
  return root;
}

export function buildWifiNode() {
  const root = new THREE.Group();
  const cyan = INTERFACE_SPECS.wlan0.color;
  root.add(mesh(new THREE.CylinderGeometry(0.55, 0.7, 0.35, 16), M.matte('#1f2937'), 0, 0.17, 0));
  root.add(mesh(new THREE.CylinderGeometry(0.15, 0.24, 8, 14), M.metal('#334155', 0.45), 0, 4.2, 0));
  root.add(mesh(new THREE.BoxGeometry(0.12, 0.12, 1.8), M.metal('#475569'), 0, 7.55, 0));
  root.add(mesh(new RoundedBoxGeometry(0.62, 0.78, 1.0, 3, 0.1), M.metal('#e2e8f0', 0.35), 0.18, 8.15, 0));
  root.add(mesh(new THREE.BoxGeometry(0.03, 0.08, 0.7), M.glow(cyan, 3.6), 0.5, 8.3, 0));
  const ring = mesh(new THREE.TorusGeometry(0.46, 0.035, 10, 40), M.glow(cyan, 3), 0.18, 7.72, 0);
  ring.rotation.x = Math.PI / 2;
  root.add(ring);
  for (const side of [-1, 1]) {
    const ant = mesh(new THREE.CylinderGeometry(0.035, 0.045, 1.0, 8), M.matte('#0f172a'), 0.18, 9.0, side * 0.36);
    ant.rotation.x = side * 0.18;
    root.add(ant);
    root.add(mesh(new THREE.SphereGeometry(0.07, 12, 8), M.glow(cyan, 4), 0.18, 9.5, side * 0.45));
  }
  anchor(root, 0.3, 8.4, 0);
  return root;
}

export function build5GTower() {
  const root = new THREE.Group();
  const green = INTERFACE_SPECS.wwan0.color;
  const H = 27;
  const r0 = 2.7;
  const r1 = 1.05;
  const legPoint = (k, h) => {
    const r = r0 + (r1 - r0) * (h / H);
    const a = (k / 6) * Math.PI * 2;
    return new THREE.Vector3(Math.cos(a) * r, h, Math.sin(a) * r);
  };
  const geos = [];
  const levels = 9;
  for (let k = 0; k < 6; k++) {
    geos.push(strut(legPoint(k, 0), legPoint(k, H), 0.1));
    for (let i = 0; i < levels; i++) {
      const h0 = (i / levels) * H;
      const h1 = ((i + 1) / levels) * H;
      geos.push(strut(legPoint(k, h0), legPoint((k + 1) % 6, h1), 0.035));
      geos.push(strut(legPoint(k, h1), legPoint((k + 1) % 6, h1), 0.05));
    }
  }
  root.add(new THREE.Mesh(mergeGeometries(geos), M.metal('#64748b', 0.5)));
  root.add(mesh(new THREE.CylinderGeometry(r0 + 0.6, r0 + 0.9, 0.5, 6), M.matte('#1f2937'), 0, 0.25, 0));
  root.add(mesh(new THREE.CylinderGeometry(2.0, 2.0, 0.25, 6), M.metal('#334155'), 0, H + 0.2, 0));
  root.add(mesh(new THREE.CylinderGeometry(0.12, 0.12, 3.2, 8), M.metal('#94a3b8'), 0, H + 1.8, 0));
  root.add(mesh(new THREE.SphereGeometry(0.22, 16, 12), M.glow('#ff2d55', 5), 0, H + 3.45, 0));
  for (let i = 0; i < 3; i++) {
    const a = (i / 3) * Math.PI * 2 + Math.PI / 6;
    const panel = new THREE.Group();
    panel.add(mesh(new RoundedBoxGeometry(0.34, 2.7, 1.0, 2, 0.06), M.metal('#e5e7eb', 0.4)));
    panel.add(mesh(new THREE.BoxGeometry(0.05, 2.3, 0.14), M.glow(green, 3.6), 0.19, 0, 0));
    panel.position.set(Math.cos(a) * 1.9, H + 1.5, Math.sin(a) * 1.9);
    panel.rotation.y = -a;
    panel.rotation.z = -0.1; // electrical down-tilt
    root.add(panel);
  }
  root.add(mesh(new THREE.TorusGeometry(2.05, 0.05, 6, 6), M.glow(green, 2.4), 0, H + 0.36, 0).rotateX(Math.PI / 2));
  anchor(root, 0, H + 1.5, 0);
  return root;
}

export function buildSatellite() {
  const root = new THREE.Group();
  const amber = INTERFACE_SPECS.sat0.color;
  // Gold-foil core with crinkled vertices.
  const core = new THREE.BoxGeometry(2.0, 2.0, 2.6, 5, 5, 6);
  const p = core.attributes.position;
  for (let i = 0; i < p.count; i++) {
    const n = Math.sin(p.getX(i) * 9.1) * Math.cos(p.getZ(i) * 7.3) * Math.sin(p.getY(i) * 5.7);
    p.setXYZ(i, p.getX(i) * (1 + n * 0.025), p.getY(i) * (1 + n * 0.025), p.getZ(i) * (1 + n * 0.025));
  }
  core.computeVertexNormals();
  root.add(new THREE.Mesh(core, M.gold()));
  root.add(mesh(new THREE.BoxGeometry(2.1, 0.12, 2.7), M.metal('#cbd5e1', 0.3), 0, 1.02, 0));
  // Photovoltaic wings with cell grid.
  for (const side of [-1, 1]) {
    root.add(mesh(new THREE.CylinderGeometry(0.06, 0.06, 1.6, 8), M.metal('#94a3b8'), 0, 0, side * 2.1).rotateX(Math.PI / 2));
    const wing = new THREE.Group();
    wing.add(mesh(new THREE.BoxGeometry(2.4, 0.07, 6.2), M.pv()));
    const grid = [];
    for (let gx = -1.2; gx <= 1.21; gx += 0.6) grid.push(gx, 0.05, -3.1, gx, 0.05, 3.1);
    for (let gz = -3.1; gz <= 3.11; gz += 0.62) grid.push(-1.2, 0.05, gz, 1.2, 0.05, gz);
    const gridGeo = new THREE.BufferGeometry();
    gridGeo.setAttribute('position', new THREE.Float32BufferAttribute(grid, 3));
    wing.add(new THREE.LineSegments(gridGeo, new THREE.LineBasicMaterial({ color: '#60a5fa', transparent: true, opacity: 0.55 })));
    wing.position.set(0, 0, side * 6.0);
    root.add(wing);
  }
  // Downward transponder dish (paraboloid) with amber feed horn.
  const prof = [];
  for (let i = 0; i <= 12; i++) {
    const r = (i / 12) * 1.3;
    prof.push(new THREE.Vector2(r, (r * r) / 2.4));
  }
  const dish = new THREE.Mesh(
    new THREE.LatheGeometry(prof, 32),
    new THREE.MeshStandardMaterial({ color: '#e2e8f0', metalness: 0.6, roughness: 0.3, side: THREE.DoubleSide }),
  );
  dish.rotation.x = Math.PI;
  dish.position.y = -1.25;
  root.add(dish);
  root.add(mesh(new THREE.TorusGeometry(1.3, 0.05, 8, 40), M.glow(amber, 3.4), 0, -1.95, 0).rotateX(Math.PI / 2));
  root.add(mesh(new THREE.CylinderGeometry(0.04, 0.04, 0.9, 6), M.metal('#94a3b8'), 0, -1.7, 0));
  root.add(mesh(new THREE.ConeGeometry(0.16, 0.34, 16), M.glow(amber, 4.5), 0, -2.2, 0).rotateX(Math.PI));
  root.add(mesh(new THREE.CylinderGeometry(0.02, 0.02, 1.4, 6), M.metal('#cbd5e1'), 0.6, 1.7, 0.6));
  anchor(root, 0, -2.35, 0);
  return root;
}

const BUILDERS = { wired: buildWiredNode, wifi: buildWifiNode, cellular: build5GTower, satellite: buildSatellite };

function makeLabel(id, color, sub) {
  const el = document.createElement('div');
  el.className = 'node-label';
  el.style.setProperty('--c', color);
  el.innerHTML = `<span class="dot"></span><span class="name">${id}</span><span class="sub">${sub}</span>`;
  const obj = new CSS2DObject(el);
  return { obj, el, sub: el.querySelector('.sub') };
}

function makeCoverageRings(color, radius) {
  const group = new THREE.Group();
  const rings = [];
  for (let i = 0; i < 3; i++) {
    const mat = new THREE.MeshBasicMaterial({
      color: new THREE.Color(color).multiplyScalar(1.4),
      transparent: true,
      opacity: 0,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      toneMapped: false,
      side: THREE.DoubleSide,
    });
    const ring = new THREE.Mesh(new THREE.RingGeometry(0.988, 1, 128), mat);
    ring.rotation.x = -Math.PI / 2;
    ring.position.y = 0.06;
    ring.userData.phase = i / 3;
    group.add(ring);
    rings.push(ring);
  }
  group.userData.radius = radius;
  return { group, rings };
}

export class NetworkNodeManager {
  constructor(sceneManager, world) {
    this.sm = sceneManager;
    this.world = world;
    this.group = new THREE.Group();
    this.group.name = 'NetworkNodes';
    this.sm.scene.add(this.group);
    this.nodes = {};
    this.satellites = [];
    this.usedGLB = {};
    this._tmp = new THREE.Vector3();
  }

  async load() {
    const layout = this.world.nodes;
    const specs = [
      ['eth0', layout.eth0, 'Gigabit dock'],
      ['wlan0', layout.wlan0, 'Wi-Fi 6 AP'],
      ['wwan0', layout.wwan0, '5G SA gNB'],
    ];
    const files = [...specs.map(([, n]) => n.model), layout.sat0.model];
    const loaded = await Promise.all(files.map((f) => loadGLB(f)));

    specs.forEach(([id, spec, sub], i) => {
      const glb = loaded[i];
      this.usedGLB[id] = !!glb;
      const root = glb ?? BUILDERS[spec.kind]();
      this._registerNode(id, root, spec.position, INTERFACE_SPECS[id].color, sub);
    });

    const satTemplate = loaded[3];
    this.usedGLB.sat0 = !!satTemplate;
    const count = layout.sat0.orbit.count;
    for (let k = 0; k < count; k++) {
      let root;
      if (satTemplate) {
        root = satTemplate.clone(true);
        root.traverse((o) => {
          if (o.isMesh) o.material = Array.isArray(o.material) ? o.material.map((m) => m.clone()) : o.material.clone();
        });
      } else root = buildSatellite();
      root.scale.setScalar(1.15);
      const holder = new THREE.Group();
      holder.add(root);
      this.group.add(holder);
      const emissives = collectEmissives(root, 2.4);
      const label = makeLabel(`LEO-${k + 1}`, INTERFACE_SPECS.sat0.color, 'sat0 · 550 km');
      label.obj.position.set(0, 4.2, 0);
      holder.add(label.obj);
      this.satellites.push({
        id: `LEO-${k + 1}`,
        holder,
        root,
        anchor: root.getObjectByName('BeamAnchor') ?? anchor(root, 0, -2.3, 0),
        emissives,
        label,
      });
    }
    return this;
  }

  _registerNode(id, root, position, color, sub) {
    const holder = new THREE.Group();
    holder.position.set(position.x, position.y, position.z);
    holder.add(root);
    this.group.add(holder);
    const anchorObj = root.getObjectByName('BeamAnchor') ?? anchor(root, 0, 2, 0);
    const emissives = collectEmissives(root, 2.2);
    const label = makeLabel(id, color, sub);
    const box = new THREE.Box3().setFromObject(root);
    label.obj.position.set(0, box.max.y - position.y + 1.6, 0);
    holder.add(label.obj);
    let coverage = null;
    if (id === 'wlan0' || id === 'wwan0') {
      coverage = makeCoverageRings(color, id === 'wlan0' ? 62 : 95);
      holder.add(coverage.group);
    }
    this.nodes[id] = { id, holder, root, anchor: anchorObj, emissives, label, coverage, subText: sub };
  }

  /** World position where a beam to `id` attaches (sat0 → the serving satellite). */
  getAnchorWorldPosition(id, target, servingSat) {
    if (id === 'sat0') {
      const sat = this.satellites.find((s) => s.id === servingSat) ?? this.satellites[0];
      return sat.anchor.getWorldPosition(target);
    }
    return this.nodes[id].anchor.getWorldPosition(target);
  }

  _setEmissive(list, factor, tint) {
    for (const m of list) {
      m.emissiveIntensity = m.userData.baseEmissive * factor;
      if (tint) m.emissive.copy(tint);
      else m.emissive.copy(m.userData.baseEmissiveColor);
    }
  }

  /**
   * @param {object} render interpolated render state (satellite positions)
   * @param {object} snapshot latest simulation snapshot
   * @param {string} focusId engine whose view drives serving-satellite highlight
   */
  update(render, snapshot, focusId, time) {
    const env = snapshot.env;

    // Satellites: ephemeris + slow attitude drift.
    render.satellites.forEach((s, i) => {
      const sat = this.satellites[i];
      if (!sat) return;
      sat.holder.position.set(s.x, s.y, s.z);
      sat.root.rotation.y = Math.sin(time * 0.15 + i) * 0.25;
      sat.root.rotation.z = Math.sin(time * 0.21 + i * 2) * 0.05;
    });
    const serving = snapshot.agents[focusId]?.links?.sat0?.info?.servingSat;
    for (const sat of this.satellites) {
      const isServing = sat.id === serving;
      sat.label.sub.textContent = isServing ? 'sat0 · SERVING' : 'sat0 · standby';
      sat.label.el.style.opacity = isServing ? '1' : '0.55';
    }

    // 5G cell health (outage fault).
    const cell = this.nodes.wwan0;
    const health = env.cellHealth;
    const offline = health < 0.999;
    this._setEmissive(cell.emissives, offline ? 0.08 + 0.4 * health : 1, offline ? OUTAGE_TINT : null);
    cell.label.el.classList.toggle('is-offline', offline);
    cell.label.sub.textContent = offline ? (health <= 0 ? 'CELL OUTAGE' : 'RESTARTING') : cell.subText;

    // Wi-Fi fade (interference / blockage).
    const wifi = this.nodes.wlan0;
    const fade = env.wifiFadeDb;
    const flicker = fade > 1 ? 0.35 + 0.65 * Math.abs(Math.sin(time * 23)) * (1 - fade / 60) : 1;
    this._setEmissive(wifi.emissives, flicker, null);
    wifi.label.el.classList.toggle('is-offline', fade > 20);
    wifi.label.sub.textContent = fade > 1 ? `FADE −${fade.toFixed(0)} dB` : wifi.subText;

    // Coverage ripples.
    for (const node of [wifi, cell]) {
      const cov = node.coverage;
      const alive = node === cell ? !offline : fade < 20;
      const R = cov.group.userData.radius;
      for (const ring of cov.rings) {
        const ph = (time * 0.18 + ring.userData.phase) % 1;
        const scale = 2 + ph * R;
        ring.scale.set(scale, scale, 1);
        ring.material.opacity = alive ? (1 - ph) * 0.13 : 0;
      }
    }
  }
}
